"""Four synchronized lossless original RGB sources for right-half cases."""

import subprocess
from pathlib import Path
from threading import Condition
from time import monotonic

CAMERAS = {
    "overview": ((-10, 0, 10), (-12, 0, 0), (1920, 1080), 95),
    "approach": ((1.2, 0, 2), (0, 0, 0), (1280, 720), 90),
    "reference_corner": ((-3, 2.5, 2.6), (-7, 0, 0), (1280, 720), 100),
    "driver_reference": ((0.6, -0.35, 1.6), (0, 0, 0), (1280, 720), 85),
}


class LosslessSourceSink:
    def __init__(self, output, name, *, popen=subprocess.Popen):
        if name not in CAMERAS:
            raise ValueError("Unknown right-half source camera")
        path = Path(output) / (name + ".mkv")
        if path.exists():
            raise ValueError("Retain prior source camera")
        width, height = CAMERAS[name][2]
        self.frame_bytes = width * height * 4
        self.process = popen(["ffmpeg", "-nostdin", "-loglevel", "error", "-y",
                              "-f", "rawvideo", "-pixel_format", "bgra",
                              "-video_size", f"{width}x{height}", "-framerate", "20",
                              "-i", "pipe:0", "-an", "-c:v", "ffv1", str(path)],
                             stdin=subprocess.PIPE)
        self.closed = False

    def write(self, image):
        if self.closed or len(image.raw_data) != self.frame_bytes:
            raise ValueError("Original source camera byte count changed")
        self.process.stdin.write(image.raw_data)

    def close(self):
        if not self.closed:
            self.closed = True
            self.process.stdin.close()
            if self.process.wait() != 0:
                raise ValueError("Right-half source encoder failed")


class RightHalfCameraCapture:
    def __init__(self, world, carla_module, ego, sinks):
        if set(sinks) != set(CAMERAS):
            raise ValueError("Exactly four named right-half camera sinks required")
        self.sinks = sinks
        self.frames = {name: set() for name in CAMERAS}
        self.condition = Condition()
        self.errors = []
        self.sensors = []
        self.closed = False
        try:
            for name, (location, rotation, size, fov) in CAMERAS.items():
                blueprint = world.get_blueprint_library().find("sensor.camera.rgb")
                for key, value in (("image_size_x", size[0]), ("image_size_y", size[1]),
                                   ("fov", fov), ("sensor_tick", 0.05)):
                    blueprint.set_attribute(key, str(value))
                transform = carla_module.Transform(
                    carla_module.Location(*location), carla_module.Rotation(*rotation))
                sensor = world.spawn_actor(blueprint, transform, attach_to=ego)
                self.sensors.append(sensor)
                sensor.listen(lambda image, source=name: self._receive(source, image))
        except BaseException:
            self.close()
            raise

    def _receive(self, name, image):
        with self.condition:
            if self.closed:
                return
            try:
                if image.frame in self.frames[name]:
                    raise ValueError("Duplicate original source camera frame")
                if (image.width, image.height) != CAMERAS[name][2]:
                    raise ValueError("Original source camera dimensions changed")
                self.sinks[name].write(image)
                self.frames[name].add(image.frame)
            except BaseException as error:
                self.errors.append(error)
            finally:
                self.condition.notify_all()

    def wait_for_frame(self, frame, *, timeout_s=10):
        deadline = monotonic() + timeout_s
        with self.condition:
            while True:
                if self.errors:
                    raise ValueError("Right-half source camera callback failed") from self.errors[0]
                if all(frame in observed for observed in self.frames.values()):
                    return
                remaining = deadline - monotonic()
                if remaining <= 0:
                    raise ValueError("Missing original right-half camera frame")
                self.condition.wait(remaining)

    def verify(self, frames):
        expected = set(frames)
        if not expected or any(observed != expected for observed in self.frames.values()):
            raise ValueError("Missing or extra original camera frames")
        return {name: len(expected) for name in CAMERAS}

    def close(self):
        if not self.closed:
            self.closed = True
            for sensor in reversed(self.sensors):
                sensor.stop()
                sensor.destroy()

"""CARLA-lazy two-way baseline route and body-side controller primitives."""

from math import atan2, hypot

from road_source_capture import _forward, _opposing_neighbor, _xy


def select_two_way_route(world_map, *, steps=16, spacing_m=2.5):
    if type(steps) is not int or steps < 10 or spacing_m <= 0:
        raise ValueError("Invalid two-way baseline route request")
    for spawn in world_map.get_spawn_points():
        start = world_map.get_waypoint(spawn.location)
        if start is None or start.is_junction:
            continue
        try:
            _opposing_neighbor(start)
        except ValueError:
            continue
        route = [start]
        for _ in range(steps):
            options = [item for item in route[-1].next(spacing_m)
                       if item.road_id == start.road_id and
                       item.lane_id == start.lane_id and not item.is_junction]
            if len(options) != 1:
                break
            try:
                _opposing_neighbor(options[0])
            except ValueError:
                break
            route.append(options[0])
        if len(route) == steps + 1:
            return route
    raise ValueError("No connected two-way route with opposing centerline")


def baseline_targets(route, *, body_side):
    if body_side not in ("right", "left") or len(route) < 11:
        raise ValueError("Invalid baseline body-side request")
    targets = []
    for waypoint in route:
        center = _xy(waypoint.transform.location)
        opposite = _opposing_neighbor(waypoint)
        if body_side == "right":
            target = center
        else:
            target = _xy(opposite.transform.location)
        targets.append(target)
    if any(hypot(b[0]-a[0], b[1]-a[1]) < 0.25
           for a, b in zip(targets, targets[1:])):
        raise ValueError("Two-way route targets are not distinct")
    return {"targets_xy_m": targets, "body_side": body_side,
            "other_vehicle_start_xy_m": list(_xy(route[8].transform.location)),
            "other_vehicle_role": "same-direction lead vehicle",
            "legal_exception_decided": False}


def control_step(position_xy, heading_xy, velocity_xy, target_xy,
                 *, target_speed_mps=5.0):
    dx, dy = target_xy[0] - position_xy[0], target_xy[1] - position_xy[1]
    if hypot(dx, dy) < 0.2:
        raise ValueError("Route target too near for feedback")
    hx, hy = heading_xy
    norm = hypot(hx, hy)
    if norm < 1e-6:
        raise ValueError("Native vehicle heading undefined")
    hx, hy = hx / norm, hy / norm
    error = atan2(hx * dy - hy * dx, hx * dx + hy * dy)
    steer = max(-0.5, min(0.5, 0.8 * error))
    speed = hypot(*velocity_xy)
    throttle = max(0.0, min(0.45, 0.22 * (target_speed_mps - speed)))
    brake = max(0.0, min(0.4, 0.16 * (speed - target_speed_mps)))
    return {"throttle": throttle, "steer": steer, "brake": brake}

"""Original-frame vehicle body position relative to the highway's right half.

The road tangent is the map traffic direction, not the ego heading. Width and
exception context are observations; no legal width threshold is supplied here.
"""

from hashlib import sha256
import json
from math import hypot, isfinite
from pathlib import Path

from shapely.geometry import Polygon


EXCEPTIONS = ('passing_same_direction', 'right_half_closed', 'three_lane_highway',
              'posted_one_way', 'insufficient_width')


def _source(path, label):
    path = Path(path)
    if not path.is_file() or not path.read_bytes():
        raise ValueError('Missing required original source: ' + label)
    raw = path.read_bytes()
    return raw, sha256(raw).hexdigest()


def _point(value, label):
    if not isinstance(value, list) or len(value) != 2:
        raise ValueError('Missing original ' + label)
    try:
        point = tuple(float(v) for v in value)
    except (TypeError, ValueError) as error:
        raise ValueError('Invalid original ' + label) from error
    if not all(isfinite(v) for v in point):
        raise ValueError('Invalid original ' + label)
    return point


def measure(road_frames_path, context_path):
    raw, frame_sha = _source(road_frames_path, 'ego_road_frames.jsonl')
    context_raw, context_sha = _source(context_path, 'road_exception_context.json')
    try:
        rows = [json.loads(line) for line in raw.splitlines()]
        context = json.loads(context_raw)
    except (UnicodeDecodeError, json.JSONDecodeError) as error:
        raise ValueError('Invalid original right-half source') from error
    if len(rows) < 2:
        raise ValueError('Right-half measurement needs multiple original frames')
    if not isinstance(context, dict):
        raise ValueError('Exception context must be an object')
    exceptions = {}
    for key in EXCEPTIONS:
        item = context.get(key)
        if not isinstance(item, dict) or 'value' not in item:
            raise ValueError('Missing separately reviewed exception: ' + key)
        value, source = item['value'], item.get('source_ref')
        if value is not None and (type(value) is not bool or not isinstance(source, str) or not source):
            raise ValueError('Known exception needs cited source: ' + key)
        if value is None and source is not None:
            raise ValueError('Unknown exception cannot cite a decided value: ' + key)
        exceptions[key] = {'value': value, 'source_ref': source}
    observations = []
    previous = None
    for row in rows:
        frame, time_s = row.get('frame'), row.get('time_s')
        if type(frame) is not int or type(time_s) not in (int, float) or not isfinite(time_s):
            raise ValueError('Original right-half frame/time invalid')
        if previous is not None and (frame != previous[0] + 1 or abs(time_s - previous[1] - .05) > 1e-4):
            raise ValueError('Original right-half frames are not continuous at 20 Hz')
        previous = frame, time_s
        center = _point(row.get('road_center_xy'), 'road centre')
        tangent = _point(row.get('road_travel_tangent_xy'), 'traffic direction')
        norm = hypot(*tangent)
        if norm < 1e-6:
            raise ValueError('Original traffic direction is degenerate')
        corners = row.get('ego_corners_xy')
        if not isinstance(corners, list) or len(corners) != 4:
            raise ValueError('Original ego footprint needs four corners')
        corners = [_point(v, 'ego footprint') for v in corners]
        polygon = Polygon(corners)
        if not polygon.is_valid or polygon.area <= 0:
            raise ValueError('Original ego footprint is degenerate')
        try:
            width = float(row['road_width_m'])
        except (KeyError, TypeError, ValueError) as error:
            raise ValueError('Original highway width missing') from error
        if not isfinite(width) or width <= 0:
            raise ValueError('Original highway width invalid')
        lateral = [((tangent[0] * (point[1] - center[1]) -
                     tangent[1] * (point[0] - center[0])) / norm)
                   for point in corners]
        observations.append({
            'frame': frame, 'time_s': time_s,
            'road_id': row.get('road_id'), 'lane_id': row.get('lane_id'),
            'road_width_m': width,
            'minimum_signed_lateral_m': min(lateral),
            'maximum_signed_lateral_m': max(lateral),
            'whole_body_right_half': max(lateral) <= 0,
            'whole_body_left_half': min(lateral) >= 0,
            'body_crosses_centerline': min(lateral) < 0 < max(lateral),
        })
    return {'format': 'worker-right-half-observation',
            'sources': {'ego_road_frames.jsonl': frame_sha,
                        'road_exception_context.json': context_sha},
            'observations': observations, 'exception_context': exceptions,
            'sufficient_width_legal_judgment': None,
            'passing_law_legal_judgment': None,
            'right_half_legal_judgment': None}

"""Measured narrow two-way road candidate; legal sufficiency stays undecided."""
from math import hypot

from road_source_capture import _opposing_neighbor
from right_half_route import baseline_targets


MAX_CANDIDATE_WIDTH_M = 6.5


def measured_width(waypoint):
    other = _opposing_neighbor(waypoint)
    own, opposing = float(waypoint.lane_width), float(other.lane_width)
    if min(own, opposing) <= 0:
        raise ValueError('Narrow road source lane width invalid')
    return own + opposing


def select_narrow_route(world_map, *, steps=16, spacing_m=2.5,
                        max_candidate_width_m=MAX_CANDIDATE_WIDTH_M):
    if type(steps) is not int or steps < 10 or spacing_m <= 0 or max_candidate_width_m <= 0:
        raise ValueError('Invalid narrow road candidate request')
    for spawn in world_map.get_spawn_points():
        start = world_map.get_waypoint(spawn.location)
        if start is None or start.is_junction:
            continue
        try:
            width = measured_width(start)
        except ValueError:
            continue
        if width > max_candidate_width_m:
            continue
        route = [start]
        for _ in range(steps):
            options = [item for item in route[-1].next(spacing_m)
                       if item.road_id == start.road_id and item.lane_id == start.lane_id
                       and not item.is_junction]
            if len(options) != 1:
                break
            try:
                width = measured_width(options[0])
            except ValueError:
                break
            if width > max_candidate_width_m:
                break
            route.append(options[0])
        if len(route) == steps + 1:
            return route
    raise ValueError('No connected measured narrow two-way road candidate')


def narrow_targets(route, *, max_candidate_width_m=MAX_CANDIDATE_WIDTH_M):
    widths = [measured_width(item) for item in route]
    if not widths or max(widths) > max_candidate_width_m:
        raise ValueError('Narrow candidate route width exceeds screen')
    targets = baseline_targets(route, body_side='left')
    targets['measured_road_width_m'] = widths
    targets['max_candidate_width_m'] = max_candidate_width_m
    targets['legal_sufficiency_decided'] = False
    return targets


def body_width_m(actor):
    vertices = actor.bounding_box.get_world_vertices(actor.get_transform())
    if len(vertices) != 8:
        raise ValueError('Native body width needs eight original vertices')
    points = {(float(point.x), float(point.y)) for point in vertices}
    if len(points) != 4:
        raise ValueError('Native body width needs four footprint corners')
    distances = sorted(hypot(b[0] - a[0], b[1] - a[1]) for a in points for b in points if a != b)
    if len(distances) != 12 or distances[0] <= 0:
        raise ValueError('Native body footprint invalid')
    return distances[0]

"""Measured narrow-road selector and original body-width controls."""
import sys
from pathlib import Path
import unittest

HERE = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(HERE))
from right_half_narrow import body_width_m, narrow_targets, select_narrow_route


class Point:
    def __init__(self, x, y, z=0):
        self.x, self.y, self.z = x, y, z


class Transform:
    def __init__(self, x, y, direction):
        self.location = Point(x, y)
        self.direction = direction

    def get_forward_vector(self):
        return Point(*self.direction)


class Lane:
    lane_type = 'Driving'
    road_id = 8
    is_junction = False

    def __init__(self, x, y, direction, lane_id, width):
        self.transform = Transform(x, y, direction)
        self.lane_id = lane_id
        self.lane_width = width
        self.other = self.following = None

    def get_left_lane(self):
        return self.other

    def get_right_lane(self):
        return None

    def next(self, spacing):
        return [self.following] if self.following else []


def pair(x, width=3):
    right = Lane(x, -width / 2, (1, 0), -1, width)
    left = Lane(x, width / 2, (-1, 0), 1, width)
    right.other, left.other = left, right
    return right


class Map:
    def __init__(self, width):
        self.route = [pair(i * 2.5, width) for i in range(17)]
        for before, after in zip(self.route, self.route[1:]):
            before.following = after

    def get_spawn_points(self):
        return [self.route[0].transform]

    def get_waypoint(self, location):
        return self.route[0]


class Body:
    def __init__(self):
        self.bounding_box = self

    def get_transform(self):
        return object()

    def get_world_vertices(self, transform):
        return [Point(x, y, z) for z in (0, 1.5)
                for x in (-2.4, 2.4) for y in (-.9, .9)]


class NarrowTest(unittest.TestCase):
    def test_measured_route_and_left_targets(self):
        route = select_narrow_route(Map(3))
        target = narrow_targets(route)
        self.assertEqual(len(target['targets_xy_m']), 17)
        self.assertEqual(target['measured_road_width_m'], [6.] * 17)
        self.assertTrue(all(y == 1.5 for _, y in target['targets_xy_m']))
        self.assertFalse(target['legal_sufficiency_decided'])
        self.assertAlmostEqual(body_width_m(Body()), 1.8)

    def test_wider_road_and_missing_opposite_rejected(self):
        with self.assertRaisesRegex(ValueError, 'No connected measured narrow'):
            select_narrow_route(Map(3.5))
        network = Map(3)
        network.route[5].other = None
        with self.assertRaisesRegex(ValueError, 'No connected measured narrow'):
            select_narrow_route(network)
